struct ProcIO {
    uint32 iop_sync;  /* I/O process descriptor identifier 0x496f496f (IoIo) */
    uint32 iop_id;  /* process (and I/O process) id */
    struct ProcIO * iop_pproc;  /* previous process in the new I/O queue */
    struct ProcIO * iop_nproc;  /* next process in the new I/O queue */
    uint32 iop_dlkn;  /* next process in the deadlock chain */
    uint32 iop_sched;  /* process scheduling priority */
    uint32 iop_owner;  /* process owner */
    uint16 iop_prior;  /* process priority */
    uint16 iop_expathsz;  /* extended path table size (entries; earlier ext_count) */
    uint32 iop_rbytes;  /* bytes read by the process */
    uint32 iop_wbytes;  /* bytes written by the process */
    uint8 iop_paths[128];  /* path translation table, NUMPATHS = 32 entries (path numbers 0..31) */
    struct PathDesc * iop_de_path;  /* default EXECUTION directory path; verified in ioman_chgdir (mode bit 4 selects 0xa8). Earlier named chd (data) - swapped */
    struct PathDesc * iop_dd_path;  /* default DATA directory path (earlier cxd) */
    void * iop_as_cur;  /* current alias list element when reading */
    uint8 iop_rpthrds[128];  /* representative process threads for the paths (32 entries) */
    uint32 iop_de_rpthrd;  /* default execution directory path thread */
    uint32 iop_dd_rpthrd;  /* default data directory path thread */
    void * iop_expaths;  /* pointer to the extended path table (earlier ext_paths) */
    uint8 iop_resvd[12];  /* reserved (3 words) */
};

